3953	            (IndexType::I32, _) | (_, IndexType::I32) => IndexType::I32,
3954	            (IndexType::I64, IndexType::I64) => IndexType::I64,
3955	        };
3956	        let src_len = if src_idx_ty == len_idx_ty {
3957	            len
3958	        } else {
3959	            assert_eq!(src_idx_ty, IndexType::I64);
